{
  "groups": [
    {
      "group_id": "mortgage_distress_vulnerable",
      "rule": "credit_score_band == 'below_600' or credit_score_band == '600_659'",
      "rationale": "Borrowers with lower credit scores are more sensitive to payment shocks and demonstrate higher churn risk."
    },
    {
      "group_id": "rate_sensitive_fixed_term_near_expiry",
      "rule": "rate_type == 'fixed' and mortgage_rate_pct > 5.0 and origination_year >= 2021.0",
      "rationale": "Borrowers locked into high fixed rates during market peaks are actively shopping for more competitive market offerings."
    },
    {
      "group_id": "high_income_stable_wealthy",
      "rule": "household_income_cad >= 150000 and has_investments == True",
      "rationale": "High net worth individuals with investments are typically less price sensitive and maintain long term retention through holistic banking relationships."
    },
    {
      "group_id": "early_career_expanding_family",
      "rule": "primary_borrower_age < 35 and n_children >= 2",
      "rationale": "Young families face significant household liquidity constraints that drive them to search for lower monthly payment options."
    },
    {
      "group_id": "variable_rate_volatility_exposed",
      "rule": "rate_type == 'variable' and payment_structure == 'adjustable_payment'",
      "rationale": "Borrowers with variable rates and fluctuating payments are experiencing the most immediate impact from interest rate changes."
    },
    {
      "group_id": "senior_retired_equity_rich",
      "rule": "employment_status == 'retired' and mortgage_balance_cad < 350000",
      "rationale": "Retired homeowners with low remaining debt balances are generally stable and exhibit lower propensity to switch lenders."
    },
    {
      "group_id": "high_utilization_debt_burdened",
      "rule": "credit_utilization_pct > 50.0 and other_debt_payment_monthly_cad > 400",
      "rationale": "Borrowers with high credit card utilization and significant secondary debt payments are financially strained and highly susceptible to switching."
    }
  ]
}
